int main(void){HDC screen=GetDC(NULL),dc=CreateCompatibleDC(screen);HBITMAP dst=CreateCompatibleBitmap(screen,4,4);HGDIOBJ old=SelectObject(dc,dst);
BYTE maskbits[]={0x80,0,0x40,0};HBITMAP mask=CreateBitmap(2,2,1,1,maskbits);BITMAPINFO bmi={0};bmi.bmiHeader.biSize=40;bmi.bmiHeader.biWidth=2;bmi.bmiHeader.biHeight=-2;bmi.bmiHeader.biPlanes=1;bmi.bmiHeader.biBitCount=32;DWORD *bits;HBITMAP color=CreateDIBSection(screen,&bmi,0,(void **)&bits,NULL,0);DWORD values[]={0x00102030,0x00405060,0x00708090,0x00a0b0c0};for(int i=0;i<4;i++)bits[i]=values[i];ICONINFO info={TRUE,20,30,mask,color};HICON icon=CreateIconIndirect(&info);puts("[");for(UINT flags=0;flags<4;flags++){char name[30];sprintf(name,"color-%u",flags);emit(dc,icon,name,flags);}emit(dc,icon,"draw-default",0xffffffff);HICON copy=CopyIcon(icon);DestroyIcon(icon);DeleteObject(mask);DeleteObject(color);emit(dc,copy,"copy-after-delete",3);HICON scaled=CopyImage(copy,IMAGE_ICON,4,4,0);DestroyIcon(copy);emit(dc,scaled,"scaled-after-delete",3);DestroyIcon(scaled);
mask=CreateBitmap(2,2,1,1,maskbits);color=CreateDIBSection(screen,&bmi,0,(void **)&bits,NULL,0);DWORD alpha[]={0x80102030,0x80405060,0x80708090,0xffa0b0c0};for(int i=0;i<4;i++)bits[i]=alpha[i];info.hbmMask=mask;info.hbmColor=color;icon=CreateIconIndirect(&info);DeleteObject(mask);DeleteObject(color);for(UINT flags=0;flags<4;flags++){char name[30];sprintf(name,"alpha-%u",flags);emit(dc,icon,name,flags);}ICONINFO copied={0};GetIconInfo(icon,&copied);HICON roundtrip=CreateIconIndirect(&copied);DeleteObject(copied.hbmMask);DeleteObject(copied.hbmColor);DestroyIcon(icon);emit(dc,roundtrip,"alpha-roundtrip",3);DestroyIcon(roundtrip);
BYTE mono[]={0x80,0,0x40,0,0xc0,0,0x40,0};mask=CreateBitmap(2,4,1,1,mono);info.hbmMask=mask;info.hbmColor=NULL;icon=CreateIconIndirect(&info);DeleteObject(mask);for(UINT flags=0;flags<4;flags++){char name[30];sprintf(name,"mono-%u",flags);emit(dc,icon,name,flags);}DestroyIcon(icon);puts("]");SelectObject(dc,old);DeleteObject(dst);DeleteDC(dc);ReleaseDC(NULL,screen);return 0;}
